--
-- Name: questionnaire_assignments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.questionnaire_assignments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    template_version_id uuid NOT NULL,
    employee_id uuid,
    assigned_by_user_id uuid NOT NULL,
    status character varying(32) DEFAULT 'assigned'::character varying NOT NULL,
    due_at timestamp with time zone,
    started_at timestamp with time zone,
    submitted_at timestamp with time zone,
    reviewed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    detached_from_employee_id uuid,
    code character varying(32) NOT NULL,
    comment text,
    context_json jsonb,
    title character varying(255),
    CONSTRAINT "CHK_questionnaire_assignments_employee_state" CHECK (((((status)::text = 'new'::text) AND (employee_id IS NULL) AND (detached_from_employee_id IS NULL)) OR (((status)::text = ANY ((ARRAY['assigned'::character varying, 'in_progress'::character varying, 'submitted'::character varying, 'changes_requested'::character varying, 'reviewed'::character varying])::text[])) AND (employee_id IS NOT NULL) AND (detached_from_employee_id IS NULL)) OR (((status)::text = 'cancelled'::text) AND (((employee_id IS NULL) AND (detached_from_employee_id IS NOT NULL)) OR ((employee_id IS NOT NULL) AND (detached_from_employee_id IS NULL)))) OR (((status)::text = 'closed'::text) AND (((employee_id IS NOT NULL) AND (detached_from_employee_id IS NULL)) OR ((employee_id IS NULL) AND (detached_from_employee_id IS NOT NULL)))))),
    CONSTRAINT "CHK_questionnaire_assignments_status" CHECK (((status)::text = ANY ((ARRAY['new'::character varying, 'assigned'::character varying, 'in_progress'::character varying, 'submitted'::character varying, 'changes_requested'::character varying, 'reviewed'::character varying, 'cancelled'::character varying, 'closed'::character varying])::text[])))
);


