    review_status character varying(32) DEFAULT 'pending'::character varying NOT NULL,
    reviewed_by_user_id uuid,
    reviewed_at timestamp with time zone,
    review_comment text,
    change_request_resolution character varying(32),
    change_request_resolved_by_user_id uuid,
    change_request_resolved_at timestamp with time zone,
    context_json jsonb,
    CONSTRAINT "CHK_questionnaire_submissions_change_request_resolution" CHECK (((change_request_resolution IS NULL) OR ((change_request_resolution)::text = ANY ((ARRAY['completed'::character varying, 'declined'::character varying])::text[])))),
    CONSTRAINT "CHK_questionnaire_submissions_review_status" CHECK (((review_status)::text = ANY ((ARRAY['pending'::character varying, 'changes_requested'::character varying, 'approved'::character varying])::text[])))
);


